class Poll:
    def __init__(self, question: str) -> None:
        self.question = question
        self.options = []          # ordered list of option names (order added)
        self.votes = {}            # option -> vote count
        self.total_votes = 0

    def add_option(self, option: str) -> None:
        if option in self.votes:
            return  # or could raise; spec doesn't say, keep idempotent
        self.options.append(option)
        self.votes[option] = 0

    def vote(self, voter: str, option: str) -> None:
        if option not in self.votes:
            raise ValueError(f"Option '{option}' does not exist")
        self.votes[option] += 1
        self.total_votes += 1

    def winner(self) -> str | None:
        if self.total_votes < 3:
            return None
        # Find max vote count, then among those pick the one added last.
        best = None
        best_count = -1
        for opt in reversed(self.options):  # last added first
            if self.votes[opt] > best_count:
                best_count = self.votes[opt]
                best = opt
        return best
